parameters.jsCode:
const input = $('When Called by Agent').item.json;
const order = $json.body?.[0];
if (!input.order_number || !input.email) {
  return { json: { found: false, response: 'Both the order number and the customer email address are required.' } };
}
if (!order) {
  return { json: { found: false, response: 'No order found for this combination of order number and email address.' } };
}
const STATE = {
  draft: 'quotation (not confirmed yet)', sent: 'quotation sent (not confirmed yet)',
  sale: 'confirmed - being prepared for delivery', done: 'locked / completed', cancel: 'cancelled',
};
const INVOICE = { invoiced: 'invoiced', 'to invoice': 'not invoiced yet', no: 'nothing to invoice', upselling: 'invoiced' };
const lines = [
  'Order ' + order.name + ': status ' + (STATE[order.state] ?? order.state),
  'Order date: ' + String(order.date_order).slice(0, 10),
  'Total: ' + Number(order.amount_total).toFixed(2) + ' ' + (order.currency_id?.[1] ?? 'EUR') + ' (incl. VAT)',
  'Invoice: ' + (INVOICE[order.invoice_status] ?? order.invoice_status),
];
if (order.commitment_date) lines.push('Promised delivery date: ' + String(order.commitment_date).slice(0, 10));
if (order.client_order_ref) lines.push('Customer reference: ' + order.client_order_ref);
return { json: { found: true, response: lines.join('\n') } };

